effect.shader:
// ============================================================================
//  OS ATRIBUTOS DE COR
// ============================================================================

float luma(vec3 c) {
    return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

/** HSL: matiz 0..1 (0 = vermelho), saturação e luminosidade. */
vec3 paraHsl(vec3 c) {
    float maior = max(c.r, max(c.g, c.b));
    float menor = min(c.r, min(c.g, c.b));
    float l = (maior + menor) * 0.5;
    float d = maior - menor;
    if (d < 1e-5) return vec3(0.0, 0.0, l);
    float s = l > 0.5 ? d / (2.0 - maior - menor) : d / (maior + menor);
    float h;
    if (maior == c.r) h = (c.g - c.b) / d + (c.g < c.b ? 6.0 : 0.0);
    else if (maior == c.g) h = (c.b - c.r) / d + 2.0;
    else h = (c.r - c.g) / d + 4.0;
    return vec3(h / 6.0, s, l);
}

float canalDaMatiz(float p, float q, float t) {
    t = t - floor(t);
    if (t < 1.0 / 6.0) return p + (q - p) * 6.0 * t;
    if (t < 0.5) return q;
    if (t < 2.0 / 3.0) return p + (q - p) * (2.0 / 3.0 - t) * 6.0;
    return p;
}

vec3 deHsl(vec3 hsl) {
    if (hsl.y < 1e-5) return vec3(hsl.z);
    float q = hsl.z < 0.5 ? hsl.z * (1.0 + hsl.y) : hsl.z + hsl.y - hsl.z * hsl.y;
    float p = 2.0 * hsl.z - q;
    return vec3(
        canalDaMatiz(p, q, hsl.x + 1.0 / 3.0),
        canalDaMatiz(p, q, hsl.x),
        canalDaMatiz(p, q, hsl.x - 1.0 / 3.0));
}

/** A fase de um pixel pelo atributo escolhido (a lista do "Get Phase From"). */
float faseDe(vec4 c, int atributo) {
    if (atributo == 0) return (c.r + c.g + c.b) / 3.0;   // Intensity: a média simples (o print)
    if (atributo == 1) return c.r;
    if (atributo == 2) return c.g;
    if (atributo == 3) return c.b;
    if (atributo == 4) return paraHsl(c.rgb).x;
    if (atributo == 5) return paraHsl(c.rgb).z;
    if (atributo == 6) return paraHsl(c.rgb).y;
    if (atributo == 7) return max(c.r, max(c.g, c.b));
    if (atributo == 8) return c.a;
    return 0.0;                                           // Zero
}

// ============================================================================
//  A RODA
// ============================================================================

/** A cor da roda em t (0 = topo, começo; 1 = topo, fim). */
vec4 naRoda(float t) {
    float x = clamp(t, 0.0, 1.0) * 256.0;
    int i = min(int(floor(x)), 255);
    float f = x - float(i);
    return mix(texelFetch(ciclo, ivec2(i, 0), 0), texelFetch(ciclo, ivec2(i + 1, 0), 0), f);
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);
    float fase = faseDe(original, getPhase);

    // ------------------------------------------------ a segunda fase
    // Sem camada escolhida o motor entrega uma textura 1×1 (empty="transparent"):
    // aí não há segunda fase.
    if (textureSize(addPhaseLayer, 0).x > 1) {
        float outra = faseDe(texture(addPhaseLayer, acScreenNorm), addPhaseFrom);
        if (addMode == 0) fase = fase + outra;                           // Wrap: dá a volta
        else if (addMode == 1) fase = min(fase + outra, 1.0);             // Clamp
        else if (addMode == 2) fase = (fase + outra) * 0.5;               // Average
        else fase = 1.0 - (1.0 - fase) * (1.0 - outra);                   // Screen
    }

    // ------------------------------------------------ a volta na roda
    // O Phase Shift positivo leva o começo no sentido horário; "Girar com o
    // tempo" é o mesmo giro andando sozinho.
    float voltas = fase * repeticoes + phaseShift / 360.0 + velocidade * acTime;
    float t = voltas - floor(voltas);
    // Uma volta inteira e exata (o branco, com uma repetição) é o FIM da roda,
    // e não o começo de novo: numa rampa, o branco tem que ficar branco.
    if (t == 0.0 && voltas > 0.0) t = 1.0;
    vec4 nova = naRoda(t);

    // ------------------------------------------------ o que a cor nova troca
    vec3 cor = original.rgb;
    if (modify == 1) {
        cor = nova.rgb;
    } else if (modify == 2) {
        cor.r = nova.r;
    } else if (modify == 3) {
        cor.g = nova.g;
    } else if (modify == 4) {
        cor.b = nova.b;
    } else if (modify >= 5 && modify <= 7) {
        vec3 a = paraHsl(original.rgb);
        vec3 b = paraHsl(nova.rgb);
        if (modify == 5) a.x = b.x;
        if (modify == 6) a.z = b.z;
        if (modify == 7) a.y = b.y;
        cor = deHsl(a);
    } else if (modify == 8) {
        // Value: o maior canal vira o da cor nova, e a cor mantém a proporção.
        float v = max(original.r, max(original.g, original.b));
        float vNovo = max(nova.r, max(nova.g, nova.b));
        cor = v > 1e-5 ? original.rgb * (vNovo / v) : vec3(vNovo);
    }

    float alfa = original.a;
    if (modifyAlpha) {
        alfa = changeEmpty ? nova.a : original.a * nova.a;
    }

    // ------------------------------------------------ em quais pixels
    float quanto = 1.0;
    if (matchMode > 0) {
        float d;
        if (matchMode == 1) {
            d = distance(original.rgb, matchColor.rgb) / sqrt(3.0);
        } else if (matchMode == 2) {
            float dh = abs(paraHsl(original.rgb).x - paraHsl(matchColor.rgb).x);
            d = min(dh, 1.0 - dh) * 2.0;
        } else {
            // Chroma: a cor sem a luz (os eixos de cor do YIQ), boa para foto:
            // a sombra de uma calça azul continua azul.
            vec2 a = vec2(dot(original.rgb, vec3(0.596, -0.274, -0.322)), dot(original.rgb, vec3(0.211, -0.523, 0.312)));
            vec2 b = vec2(dot(matchColor.rgb, vec3(0.596, -0.274, -0.322)), dot(matchColor.rgb, vec3(0.211, -0.523, 0.312)));
            d = clamp(distance(a, b) / 1.2, 0.0, 1.0);
        }
        quanto = 1.0 - smoothstep(matchTolerance, matchTolerance + matchSoftness + 0.0001, d);
    }
    if (maskMode > 0 && textureSize(maskLayer, 0).x > 1) {
        vec4 m = texture(maskLayer, acScreenNorm);
        float v = maskMode <= 2 ? luma(m.rgb) * m.a : m.a;
        if (maskMode == 2 || maskMode == 4) v = 1.0 - v;
        quanto *= v;
    }

    // ------------------------------------------------ a saída
    // Composite Over Layer desligado: só os pixels modificados aparecem.
    if (compositeOver) {
        fragColor = vec4(mix(original.rgb, clamp(cor, 0.0, 1.0), quanto), mix(original.a, alfa, quanto));
    } else {
        fragColor = vec4(clamp(cor, 0.0, 1.0), alfa * quanto);
    }
}
